def sha(path):return hashlib.sha256(path.read_bytes()).hexdigest()
def rel(path,other):
    import os
    return Path(os.path.relpath(other,path)).as_posix()

def main():
    assets=json.loads((PDF/'assets.json').read_text(encoding='utf-8'))
    available={x['file']:x for x in assets['documents'] if 'sha256' in x}
    catalog=[]
    for item in DATA:
        folder=BASE/item['folder'];notice=folder/'notices';notice.mkdir(parents=True,exist_ok=True)
        has_cad=(folder/'3D/provenance.json').exists()
        cad_note='[Modèles STEP, aperçus et provenance](3D/README.md).' if has_cad else '**Aucun modèle 3D créé.**'
        lines=[f'# {item["name"]}', '', '**Choix de conception du 13 octobre 2026**, effectué sous l’autorisation de sélectionner les pièces. Non acheté, non testé ; aucune garantie de performance du véhicule.', '',
               f'Référence : **{item["ref"]}**. Quantité prévue : **{item["qty"]}**.', '',item['why'], '', '## Caractéristiques et rôle', '', '| Donnée | Valeur / statut |','| --- | --- |']
        lines += [f'| {key} | {value} |' for key,value in item['specs'].items()]
        lines += ['', '## Documents', '', '[Notice d’intégration V3](notices/notice-integration-v3.md), [recherche et incertitudes](recherche-technique.md), [sources structurées](sources.json).']
        for name in item['pdfs']:
            if name in available:lines+=['',f'- [{name}]({rel(folder,PDF/name)}) : document original inchangé, conservé dans le dossier commun.']
        lines += ['', '## Achat et validation', '',
                  f'[Recherche Amazon France par référence](https://www.amazon.fr/s?k={quote_plus(item["q"])}) — lien de recherche, **pas une offre vérifiée**. Aucun ASIN, prix en euros, stock ou livraison n’est inventé. Les pièces à fabriquer doivent également être chiffrées.', '',
                  'Sources techniques : '+', '.join(f'[source {i+1}]({u})' for i,u in enumerate(item['urls']))+'.', '',
                  f'[Vue d’ensemble direction et transmission]({rel(folder,COMMON/"README.md")}). '+cad_note, '']
        (folder/'README.md').write_text('\n'.join(lines),encoding='utf-8')
        sources={'selected_on':DATE,'selected_by':'assistant, authorized by user','reference':item['ref'],'quantity_design':item['qty'],'purchased':False,'hardware_tested':False,'model_3d_created':has_cad,
                 'purchase_status':'Not an identified or verified Amazon offer; fabrication lines are not purchase-ready','price_eur':None,'amazon_search_url':'https://www.amazon.fr/s?k='+quote_plus(item['q']),
                 'specifications':item['specs'],'sources':[{'url':u,'type':'primary or explicitly identified supplier reference','checked_on':DATE} for u in item['urls']],
                 'documents':[dict(available[n],local_file=rel(folder,PDF/n)) for n in item['pdfs'] if n in available],'unknowns':item['pending']}
        if has_cad:sources['model_3d_manifest']='3D/provenance.json'
        (folder/'sources.json').write_text(json.dumps(sources,ensure_ascii=False,indent=2)+'\n',encoding='utf-8')
        notice_cad='[Modèles 3D d’étude et limites](../3D/README.md).' if has_cad else 'Aucun modèle 3D créé.'
        (notice/'notice-integration-v3.md').write_text(f'# Intégration V3 — {item["name"]}\n\n**Document de projet, distinct des notices constructeur.** 13 octobre 2026. Montage décrit pour l’étude ; aucun essai exécuté.\n\n'+item['notice']+'\n\nLes PDF originaux et leurs pages de référence sont liés dans la [fiche](../README.md). Confirmer les données de la variante reçue et les interfaces avant fabrication. '+notice_cad+'\n',encoding='utf-8')
        research=f'# Recherche technique — {item["name"]}\n\n'+item['why']+'\n\nLes caractéristiques publiées sont séparées des choix de conception dans la fiche. Référence sélectionnée pour l’étude ; offre, montage et performances non validés.\n\n## Points à vérifier\n\n'+'\n'.join('- '+x for x in item['pending'])+'\n\n[Retour à la fiche](README.md).\n'
        (folder/'recherche-technique.md').write_text(research,encoding='utf-8')
        catalog.append({'folder':item['folder'],'name':item['name'],'reference':item['ref'],'quantity':item['qty'],'purchased':False,'model_3d_created':has_cad,'price_eur':None})
    circ=math.pi*.063;ratio=(54/16)*(54/24);wheel40=(40/3.6)*60/circ
    calc={'wheel_diameter_mm':63,'stage_teeth':[[16,54],[24,54]],'ratio':ratio,
          'module_mm':.5,'center_distances_mm':[.5*(16+54)/2,.5*(24+54)/2],
          'wheel_rpm_40':wheel40,'intermediate_rpm_40':wheel40*(54/24),'motor_rpm_40':wheel40*ratio,
          'unloaded_motor_rpm_7_4V':4500*7.4,'unloaded_speed_kmh_7_4V':4500*7.4/ratio*circ/60*3.6,
          'not_a_performance_guarantee':True,'front_mass_kg_assumed':.8,'friction_assumed':.8,'scrub_radius_m_assumed':.004,
          'horn_to_steering_arm_ratio_assumed':1.2}
    calc['servo_static_torque_Nm_assumed']=.8*9.80665*.8*.004*1.2
    calc['servo_static_torque_kgfcm_assumed']=calc['servo_static_torque_Nm_assumed']/.0980665
    calc['servo_double_margin_kgfcm_assumed']=2*calc['servo_static_torque_kgfcm_assumed']
    assert ratio==7.59375 and calc['servo_double_margin_kgfcm_assumed']<.7
    (COMMON/'selection.json').write_text(json.dumps({'selected_on':DATE,'status':'Documented design choices; no validated purchase basket, fabrication interfaces still to validate','components':catalog,'calculations':calc,'original_docs':'notices/assets.json','no_3d_created':not any(c['model_3d_created'] for c in catalog)},ensure_ascii=False,indent=2)+'\n',encoding='utf-8')
    print('Documented',len(catalog),'component dossiers; ratio',ratio,flush=True)

if __name__=='__main__':main()
